    description: 'CRITICAL SAFETY DISTINCTION: Ceylon Cinnamon (C. verum) contains only negligible trace levels of Coumarin: safe for prolonged therapeutic use. Cassia Cinnamon contains high Coumarin concentrations: chronic therapeutic doses risk severe hepatotoxicity. trans-Cinnamaldehyde (primary volatile compound) inhibits COX and LOX cascades, while condensed tannins provide hemostatic (vasoconstriction) activity to reduce menorrhagia. Cinnamon also enhances peripheral insulin sensitivity, benefiting PCOS patients by downregulating circulating androgens.',
    history: 'One of the oldest known spices: traded along ancient spice routes for over 4,000 years. Mentioned in Chinese medical texts from 2700 BC, in the Ebers Papyrus (Egyptian, 1550 BC), and in the Bible. Ceylon cinnamon (from Sri Lanka) was the most prized commodity in the spice trade due to its superior quality and safety profile compared to Cassia.',
